"""Read-only coverage scenario for owner-approved seven-player preview.

Computes row coverage using the existing game-log audit and seven approved IDs.
Does not alter publication gates or live crosswalk.
"""
import csv
import json
from pathlib import Path

CURRENT=Path("data/verified_player_ids_2027.csv")
PREVIEW=Path("reports/2027_seven_player_approved_promotion_preview.csv")
GAME_LOG=Path("reports/2027_unmatched_player_game_rows.csv")

def main():
    # The audited game-log coverage baseline is generated by the identity audit.
    # Report the arithmetic projection from the previously audited 22 candidate
    # rows without presenting it as a fresh game-log recalculation.
    with CURRENT.open(newline="",encoding="utf-8") as f:
        current=list(csv.DictReader(f))
    with PREVIEW.open(newline="",encoding="utf-8") as f:
        preview=list(csv.DictReader(f))
    ids={r["nba_player_id"] for r in preview}
    if len(preview)!=7 or len(ids)!=7 or any(r["verified"].lower()!="true" for r in preview):
        raise ValueError("Approved preview must contain seven unique verified rows")
    existing={r["nba_player_id"] for r in current if r["verified"].lower()=="true"}
    if ids & existing:raise ValueError("Preview overlaps verified crosswalk")
    # Baseline is fixed to the audited run 40635701116. Any game-log refresh
    # requires a new live scenario calculation rather than reusing these values.
    baseline_rows, total_rows, candidate_rows=1110,1181,22
    projected=baseline_rows+candidate_rows
    print("SEVEN_PLAYER_COVERAGE_PROJECTION",json.dumps({
        "basis":"historical audited game logs run 40635701116; not a live refresh",
        "baseline_covered":baseline_rows,"candidate_game_rows":candidate_rows,
        "projected_covered":projected,"total":total_rows,
        "projected_coverage_pct":round(100*projected/total_rows,2),
        "crosswalk_modified":False,"publication_ready":False
    }))

if __name__=="__main__":main()
